static void yc101_init(void)
{
    int i;
    struct dsi_cmd_packet yc101_sleep_out = {0x05,0x11, 0x00};
    struct dsi_cmd_packet yc101_display_on = {0x05,0x29, 0x00};

    if (use_4lane) {
        for (i = 0; i < ARRAY_SIZE(yc101_cmd_list_4lane); i++) {
            dsi_write_cmd(&yc101_cmd_list_4lane[i]);
        }
    } else {
        for (i = 0; i < ARRAY_SIZE(yc101_cmd_list_2lane); i++) {
            dsi_write_cmd(&yc101_cmd_list_2lane[i]);
        }
    }
    dsi_write_cmd(&yc101_sleep_out);
    usleep_range(12 * 1000, 12 * 1000);
    dsi_write_cmd(&yc101_display_on);
    usleep_range(5 * 1000, 5 * 1000);
}

static inline int m_gpio_request(int gpio, const char *name)
{
    if (gpio < 0)
        return 0;

    int ret = gpio_request(gpio, name);
    if (ret) {
        char buf[20];
        printk(KERN_ERR "yc101: failed to request %s: %s\n", name, gpio_to_str(gpio, buf));
        return ret;
    }

    return 0;
}

static inline void m_gpio_free(int gpio)
{
    if (gpio >= 0)
        gpio_free(gpio);
}

static inline void m_gpio_direction_output(int gpio, int value)
{
    if (gpio >= 0) {
        gpio_direction_output(gpio, value);
    }
}

static int yc101_power_on(struct lcdc *lcdc)
{
    if (yc101_regulator)
        regulator_enable(yc101_regulator);

    m_gpio_direction_output(gpio_lcd_power_en, 1);
    usleep_range(5 * 1000, 5 * 1000);

    m_gpio_direction_output(gpio_lcd_rst, 1);
    usleep_range(5 * 1000, 5 * 1000);
    m_gpio_direction_output(gpio_lcd_rst, 0);
    usleep_range(1 * 1000, 1 * 1000);
    m_gpio_direction_output(gpio_lcd_rst, 1);
    usleep_range(10 * 1000, 10 * 1000);

    return 0;
}

static int yc101_power_off(struct lcdc *lcdc)
{
    m_gpio_direction_output(gpio_lcd_power_en, 0);

    if (yc101_regulator)
        regulator_disable(yc101_regulator);

    return 0;
}

static struct lcdc_data lcdc_data = {
    .name = "yc101",
    .refresh = 60,
    .xres = 800,		//H-active
    .yres = 1280,		//V-active
    .pixclock = 0, 		//自动计算

    .left_margin  = 60,
    .right_margin = 80,
    .upper_margin = 12,
    .lower_margin = 12,
    .hsync_len    = 1,
    .vsync_len    = 1,

    .fb_fmt = fb_fmt_RGB888,
    .lcd_mode = TFT_MIPI,
    .out_format = OUT_FORMAT_RGB888,

    .mipi = {
        .num_of_lanes = 2,
        .virtual_channel = 0,
        .color_coding = COLOR_CODE_24BIT,
        .data_en_polarity = AT_RISING_EDGE,
        .byte_clock = 0,
        .max_hs_to_lp_cycles = 100,
        .max_lp_to_hs_cycles = 40,
        .max_bta_cycles = 4095,
        .color_mode_polarity = AT_RISING_EDGE,
        .shut_down_polarity = AT_RISING_EDGE,
        .video_mode = VIDEO_BURST_WITH_SYNC_PULSES,

        .hsync_active_level = AT_HIGH_LEVEL,
        .vsync_active_level = AT_HIGH_LEVEL,
    },
    .height = 110,
    .width = 62,

    .power_on = yc101_power_on,
    .power_off = yc101_power_off,
    .lcd_init = yc101_init,
};

static int lcd_yc101_init(void)
{
    int ret;

    if (strcmp("-1", gpio_lcd_regulator_name) && strlen(gpio_lcd_regulator_name)) {
        yc101_regulator = regulator_get(NULL, gpio_lcd_regulator_name);
        if(!yc101_regulator) {
            printk(KERN_ERR "lcd_regulator get err!\n");
            return -EINVAL;
        }
    }

    ret = m_gpio_request(gpio_lcd_power_en, "gpio_lcd_power_en");
    if(ret)
        goto power_on_err;

    ret = m_gpio_request(gpio_lcd_rst, "gpio_lcd_rst");
    if (ret)
        goto rst_err;

    if (use_4lane) {
        lcdc_data.left_margin = 50;
        lcdc_data.upper_margin = 12;
        lcdc_data.vsync_len = 5;
        lcdc_data.mipi.num_of_lanes = 4;
    }

    ret = jzfb_register_lcd(&lcdc_data);
    if (ret < 0) {
        goto register_err;
    }

    return 0;

register_err:
    m_gpio_free(gpio_lcd_rst);
rst_err:
    m_gpio_free(gpio_lcd_power_en);
power_on_err:
    if (yc101_regulator)
        regulator_put(yc101_regulator);
    return -1;
}


static void lcd_yc101_exit(void)
{
    jzfb_unregister_lcd(&lcdc_data);

    if(yc101_regulator)
        regulator_put(yc101_regulator);

    m_gpio_free(gpio_lcd_rst);
    m_gpio_free(gpio_lcd_power_en);
}


module_init(lcd_yc101_init);
module_exit(lcd_yc101_exit);

MODULE_DESCRIPTION("Ingenic Soc yc101_lcd driver");
MODULE_LICENSE("GPL");
